using App.Common;
using App.Entities;

namespace App.Repositories;

/// <summary>Keeps notes rows in memory, for tests and for trying the services without a database.</summary>
public class MemoryNoteRepository : INoteRepository
{
    private readonly Dictionary<string, Note> rows = [];

    /// <summary>The key of a row, as a list of its key values.</summary>
    private static object[] KeyOf(Note row) => [row.Id];

    private static string KeyText(Note row) => string.Join("|", KeyOf(row));

    /// <summary>Orders two keys value by value.</summary>
    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<Note> Visible() =>
        rows.Values.Where(row => true).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public Task<Note?> FindByIdAsync(int id)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Id, id)));
    }

    public Task<Page<Note>> ListAsync(int offset, int limit)
    {
        var rows = Visible().ToList();
        return Task.FromResult(new Page<Note>(rows.Skip(offset).Take(limit).ToList(), rows.Count, offset, limit));
    }

    public Task<List<Note>> ListByAuthorIdAsync(int authorId)
    {
        return Task.FromResult(Visible().Where(row => Equals(row.AuthorId, authorId)).ToList());
    }

    public Task<Note> InsertAsync(Note entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task<Note> UpdateAsync(Note entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task DeleteAsync(Note entity)
    {
        rows.Remove(KeyText(entity));
        return Task.CompletedTask;
    }
}

