using App;
using App.Common;
using App.Dtos;
using App.Entities;
using App.Errors;

namespace App.Services;

/// <summary>Operations on notes. Repositories commit every write.</summary>
public class NoteService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "notes" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Note? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Id");
            if (value is null)
                if (creating || values.ContainsKey("Id")) errors.Add(new FieldError("_id", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Text");
            if (value is null)
                if (creating || values.ContainsKey("Text")) errors.Add(new FieldError("text", "is required"));
        }
        {
            var value = values.GetValueOrDefault("AuthorId");
            if (value is null)
                if (creating || values.ContainsKey("AuthorId")) errors.Add(new FieldError("authorId", "is required"));
        }
        {
            var authorId = values.TryGetValue("AuthorId", out var givenAuthorId) ? (int?)givenAuthorId : current?.AuthorId;
            if (authorId is not null && await uow.Users.FindByIdAsync(authorId.Value) is null)
                errors.Add(new FieldError("authorId", "no User has this key"));
        }
        if (errors.Count > 0) throw new ValidationFailedException("Note", errors);
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Note? current)
    {
        await ValidateAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Note entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Id", out var id)) entity.Id = (int)id!;
        if (values.TryGetValue("Text", out var text)) entity.Text = (string)text!;
        if (values.TryGetValue("AuthorId", out var authorId)) entity.AuthorId = (int)authorId!;
    }

    /// <summary>The Note with this key; NotFoundException when there is none.</summary>
    private static async Task<Note> FindAsync(IUnitOfWork uow, int id) =>
        await uow.Notes.FindByIdAsync(id) ?? throw new NotFoundException("Note", id);

    /// <summary>The Note as services return it.</summary>
    private static NoteRead Read(Note entity) => new(entity.Id, entity.Text, entity.AuthorId);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(NoteUpdate changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.Text is { IsPresent: true } text) values["Text"] = text.Value;
        if (changes.AuthorId is { IsPresent: true } authorId) values["AuthorId"] = authorId.Value;
        return values;
    }

    /// <summary>Stores a new Note after checking it.</summary>
    public async Task<NoteRead> CreateNoteAsync(NoteCreate data)
    {
        var values = new Dictionary<string, object?>();
        values["Id"] = data.Id;
        if (data.Text is not null) values["Text"] = data.Text;
        values["AuthorId"] = data.AuthorId;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            var entity = new Note();
            Apply(entity, values);
            return Read(await uow.Notes.InsertAsync(entity));
        });
    }

    /// <summary>The Note with this key; NotFoundException when there is none.</summary>
    public async Task<NoteRead> GetNoteAsync(int id) => Read(await FindAsync(uow, id));

    /// <summary>A page of notes, by primary key.</summary>
    public async Task<Page<NoteRead>> ListNotesAsync(int offset, int limit) => (await uow.Notes.ListAsync(offset, limit)).Map(Read);

    /// <summary>Changes the given values of a Note.</summary>
    public async Task<NoteRead> UpdateNoteAsync(int id, NoteUpdate changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return Read(await uow.Notes.UpdateAsync(current));
        });
    }

    /// <summary>Deletes a Note.</summary>
    public async Task DeleteNoteAsync(int id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await uow.Notes.DeleteAsync(current);
        });
    }

    /// <summary>The notes with this authorId.</summary>
    public async Task<List<NoteRead>> ListNotesByAuthorIdAsync(int authorId) => (await uow.Notes.ListByAuthorIdAsync(authorId)).Select(Read).ToList();
}

