    {
        var values = new Dictionary<string, object?>();
        if (changes.Email is { IsPresent: true } email) values["Email"] = email.Value;
        return values;
    }

    /// <summary>Stores a new User after checking it.</summary>
    public async Task<UserRead> CreateUserAsync(UserCreate data)
    {
        var values = new Dictionary<string, object?>();
        values["Id"] = data.Id;
        if (data.Email is not null) values["Email"] = data.Email;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            var entity = new User();
            Apply(entity, values);
            return Read(await uow.Users.InsertAsync(entity));
        });
    }

    /// <summary>The User with this key; NotFoundException when there is none.</summary>
    public async Task<UserRead> GetUserAsync(int id) => Read(await FindAsync(uow, id));

    /// <summary>A page of users, by primary key.</summary>
    public async Task<Page<UserRead>> ListUsersAsync(int offset, int limit) => (await uow.Users.ListAsync(offset, limit)).Map(Read);

    /// <summary>Changes the given values of a User.</summary>
    public async Task<UserRead> UpdateUserAsync(int id, UserUpdate changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
