            return Read(await uow.Users.UpdateAsync(current));
        });
    }

    /// <summary>Deletes a User.</summary>
    public async Task DeleteUserAsync(int id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if ((await uow.Notes.ListByAuthorIdAsync(current.Id)).Count > 0) throw new ConflictException("User", "rows of notes still point to it", ["notes"]);
